INSERT INTO `blog_posts` (`id`, `title`, `slug`, `content`, `excerpt`, `featured_image`, `author`, `status`, `published_at`, `created_at`, `updated_at`) VALUES
(3, '5 Skandinaviske Hårtrender Du Må Vite Om i 2025', '5-skandinaviske-h-rtrender-du-m-vite-om-i-2025', 'Intro\r\nVelkommen til Salon Exclusive-bloggen! Vi er alltid på utkikk etter de nyeste og mest inspirerende hårtrendene, og i år ser vi at Skandinavia setter sitt preg på farge, styling og teknikk. Her er fem hårtrender fra Norden som du definitivt bør vurdere – enten du vil fornye stilen, beskytte håret ditt, eller bare få inspirasjon til neste besøk hos oss.\r\n\r\n1. Scandi Slick – Minimalisme møter eleganse\r\n\r\nDen såkalte “Scandi Slick” er en lav, sleik knute med glatt, bakstrøket hår. Denne stilen gir et rent og moderne uttrykk som passer perfekt for både jobb og fest. Det er også et praktisk valg for det skandinaviske været – regn, vind og frizz? Ingen problem. \r\nAllure\r\n\r\nTips fra oss:\r\n\r\nBruk en lett stylinggel eller pomade for å oppnå glans og kontroll.\r\n\r\nDel håret med en presis midtskill og dra det tilbake i en lav knute.\r\n\r\nAvslutt med en elastisk hårstrikk og en minimalistisk klips eller usynlig strikk for et sofistikert preg.\r\n\r\n2. Den skandinaviske hårlinjen – Naturlig solbleket effekt\r\n\r\nEn trend som vokser: “Scandi Hairline”. Her lyser man opp babyhårene og hårlinjen med et par toner lysere enn resten av håret, noe som gir et mildt, solkyss-lignende uttrykk. \r\nReal Simple\r\n\r\nHvorfor vi elsker det:\r\n\r\nFremhever ansiktet og gir et mykere uttrykk.\r\n\r\nKrever mindre vedlikehold enn helt helbleking, men gir allikevel en lysende effekt.\r\n\r\nNår det gjøres profesjonelt, ser det sømløst og naturlig ut.\r\n\r\n3. Teksturert kurve – Krøllete hår får sin plass\r\n\r\nVi ser mer og mer fokus på tekstur og naturlige krøller i Skandinavia. Frisører får stadig mer kunnskap om hvordan jobbe med ulik curl-type, og det finnes kurs og workshop spesielt rettet mot dette. \r\nWe Are One\r\n\r\nRåd til deg med krøller:\r\n\r\nBe om en “look & learn”-sesjon hos oss for å utforske kutt og produkter som passer din hårtype.\r\n\r\nBruk fuktighetsgivende produkter, og unngå tung varmebehandling.\r\n\r\nLa frisøren vise deg hvordan du kan style håret hjemme for maksimal definisjon.\r\n\r\n4. Naturlige og bærekraftige produkter\r\n\r\nBærekraft har blitt en sentral del av skjønnhetsbransjen – og det gjelder håret også. Stadig flere skandinaviske salonger velger miljøvennlige, rene og hudvennlige produkter. Dette er en trend som reflekterer verdier – ikke bare estetikk.\r\n\r\nHvordan Salon Exclusive følger med:\r\n\r\nVi tilbyr (og planlegger å tilby enda mer) produkter som er fri for unødvendige kjemikalier.\r\n\r\nVi gir råd om hvordan du kan bruke mindre, men bedre produkter – for håret og miljøet.\r\n\r\n5. Sesongbaserte farge- og stylingguider\r\n\r\nI Norden påvirkes hårtrendene i stor grad av sesong. Fra mørke, varme nyanser for høst og vinter, til lyse, luftige farger på sommeren. Å tilpasse hårstilen til sesongen er ikke bare estetisk – det handler også om helse og vedlikehold.\r\n\r\nEksempel:\r\n\r\nHøst/vinter: Satse på dypere farger som brun kobber eller mørk aske.\r\n\r\nVår/sommer: Lysere balayage, pastelltoner eller “Scandi Hairline” for et lysere uttrykk.', 'Oppdag de største skandinaviske hårtrendene for 2025! Fra den elegante “Scandi Slick” til naturlig lysende “Scandi Hairline” og økt fokus på krøller og bærekraftige produkter. Få inspirasjon og profesjonelle tips fra Salon Exclusive for å finne stilen som passer deg best.', 'uploads/blog/6920e5436773c_1763763523.jpg', 'Børre', 'published', '2025-11-21 22:18:43', '2025-11-21 22:17:28', '2025-11-21 22:18:43');

