INSERT INTO `products` (`id`, `name`, `description`, `category`, `image`, `featured`, `status`, `created_at`, `updated_at`) VALUES
(2, 'Work Out Mask', 'STĀS Work Out Mask er en effektiv og tidsbesparende hårkur utviklet for deg med en aktiv livsstil. Denne dype pleiebehandlingen styrker håret, tilfører intens fuktighet og reduserer hårbrudd – perfekt å bruke før trening, i en travel hverdag eller som nattmaske. Håret blir sunnere, sterkere og mer motstandsdyktig over tid.\r\n\r\nFordeler og egenskaper\r\nDyp fukt og intensiv næring til tørt og slitt hår\r\nReduserer hårbrudd og styrker hårstråene fra rot til spiss\r\nIdeell å bruke før trening eller som behandling over natten\r\nGjør håret mer motstandsdyktig mot ytre påkjenninger\r\nPasser for alle hårtyper – spesielt skadet, tørt eller svekket hår\r\nBruksanbefaling\r\nPåfør i tørt hår, jevnt fordelt fra midtlengde til spisser\r\nLa virke i minst 30 minutter, gjerne over natten\r\nSkyll ut med sjampo, og avslutt med balsam for best resultat\r\nAktive ingredienser\r\nVitis Vinifera (druekjerneolje): Rik på antioksidanter som styrker og beskytter\r\nCocos Nucifera (kokosolje): Gir dyp fuktighet og naturlig glans\r\nCrambe Abyssinica Seed Oil: Mykgjør og gir glans uten å tynge\r\nPhytosteroler og planteekstrakter: Bidrar til reparasjon og oppbygging av håret\r\nHva gjør STĀS Work Out Mask unik?\r\nUtviklet for en aktiv hverdag – fungerer mens du trener, jobber hjemme eller sover\r\nKombinerer styrkende og fuktighetsgivende ingredienser i én behandling\r\nReduserer brudd og tørrhet uten å tynge håret\r\nGir salongresultat hjemme, uten komplisert påføring eller ventetid\r\nHvem passer den for?\r\nDeg med tørt, slitt eller kjemisk behandlet hår\r\nDeg som vil gi håret en intensiv boost mellom frisørbesøk\r\nDeg som ønsker en enkel og effektiv hårkur som passer en hektisk hverdag\r\nEgnet for både kvinner og menn med behov for styrke og pleie\r\nVekt: 150ml', 'stas', 'uploads/products/1762167624_stas1.webp', 0, 'active', '2025-11-04 10:11:27', '2025-11-04 10:11:27'),
(3, 'Stas Hairspray', 'STĀS Hairspray er en lett og effektiv hårspray som gir et naturlig hold uten å tynge håret. Den passer perfekt til alle hårtyper og gir en fin glans samtidig som den holder frisyren på plass hele dagen.\r\n\r\nFordeler og egenskaper\r\nLett hold: Gir et naturlig og fleksibelt hold uten å gjøre håret stivt.\r\nNaturlig glans: Etterlater håret med en fin og naturlig glans.\r\nAllsidig bruk: Passer til alle hårtyper og ulike frisyrestiler.\r\nEnkel påføring: Sprayes jevnt over håret for ønsket effekt.\r\nBruksanbefaling\r\nFor et naturlig hold: Hold sprayflasken like langt fra hodet som flasken er lang.\r\nFor en mer definert frisyre: Spray nærmere håret.\r\nFor en wet-look-effekt: Bruk mer produkt og spray nærmere håret.\r\nIngredienser\r\nPolyvinylpyrrolidone (PVP): Et polymer som gir håret hold og struktur.\r\nPolydimethylsiloxane: En silikonforbindelse som gir håret glans og mykhet.\r\nAlkohol: Hjelper til med å fordampe produktet raskt og gir en lett følelse.\r\nVann: Grunnlaget for produktet som løser opp de aktive ingrediensene.\r\nHva gjør STĀS Hairspray unik?\r\nSkånsom formel: Utviklet for å være mild mot håret og hodebunnen.\r\nAllsidig: Passer for både daglig bruk og spesielle anledninger.\r\nProfesjonell kvalitet: Brukt av frisører og hårstylister for å oppnå ønsket frisyre.\r\nMålgruppe\r\nAlle hårtyper: Fra fint til tykt hår, og alt imellom.\r\nDaglig bruk: Perfekt for å holde frisyren på plass hele dagen.\r\nSpesielle anledninger: Ideell for fest eller andre spesielle hendelser.', 'stas', 'uploads/products/1762168610_stas2.webp', 0, 'active', '2025-11-04 10:11:27', '2025-11-04 10:11:27'),
(4, 'Stas BRUSH MEDIUM', 'Oppdag den perfekte balansen mellom kontroll og komfort med STAS Products Hairbrush Medium – en allsidig hårbørste som glir lett gjennom håret og gir et glatt, glansfullt resultat. Den mellomstore størrelsen gjør børsten ideell til både styling og daglig bruk – uansett hårtype.\r\n\r\nUtstyrt med fleksible børstepigger og ergonomisk design, reduserer børsten risikoen for brekkasje og gir en behagelig børsteopplevelse både i vått og tørt hår. Passer utmerket til føning, detangling og jevn fordeling av produkter i håret.\r\n\r\nEgenskaper:\r\nMedium størrelse – perfekt til både hjemmebruk og reise\r\n\r\nSkånsom mot hår og hodebunn\r\n\r\nLøsner floker uten å trekke eller skade\r\n\r\nEgnet for alle hårtyper – fra fint til tykt hår\r\n\r\nKan brukes i både vått og tørt hår\r\n\r\nKomfortabelt og lett håndtak for enkel bruk\r\n\r\nBruk:\r\nBruk på tørt eller håndkletørt hår for å løse opp floker og fordele naturlige oljer jevnt i håret. Ideell som en allround børste for daglig pleie og styling.', 'stas', 'uploads/products/1762168662_stas3.webp', 0, 'active', '2025-11-04 10:11:27', '2025-11-04 10:11:27'),
(5, 'Stas Hair oil', 'Gi håret ditt et luksuriøst løft med STAS Products Hair Oil – en eksklusiv hårolje som kombinerer næring, glans og pleie i én og samme flaske. Denne lette, men svært effektive oljen er utviklet for å styrke håret fra rot til spiss, redusere frizz og etterlate det silkemykt uten å tynge.\r\n\r\nBeriket med nøye utvalgte naturlige oljer som trenger dypt inn i hårstråene, gir denne håroljen intens fuktighet, gjenoppretter hårets elastisitet og forbedrer både glans og tekstur. Perfekt både som daglig pleie og som en kur for tørt og livløst hår.\r\n\r\nPasser for alle hårtyper – også fargebehandlet hår.\r\n\r\nEgenskaper:\r\nTilfører glans og mykhet uten å tynge håret\r\n\r\nReduserer frizz og beskytter mot ytre påvirkninger\r\n\r\nFuktighetsgivende og reparerende egenskaper\r\n\r\nEgnet for alle hårtyper, inkludert tørt og skadet hår\r\n\r\nKan brukes både i tørt og fuktig hår\r\n\r\nElegant og delikat duft\r\n\r\nBruk:\r\nPåfør et par dråper i håndflatene og fordel jevnt i lengder og spisser. Kan brukes i både vått og tørt hår – etter behov.', 'stas', 'uploads/products/1762168714_stas4.webp', 1, 'active', '2025-11-04 10:11:27', '2025-11-04 10:52:11'),
(6, 'Stas DRY TEXTURIZING', 'Få salongfølelsen hjemme med STAS Products Texturizing Big Volume – en allsidig teksturspray som gir umiddelbart løft, luftig volum og en rå tekstur med naturlig bevegelse. Perfekt for deg som ønsker et fyldigere og mer definert hår uten stivhet eller tyngde.\r\n\r\nSprayen er ideell både i røttene for løft, og i lengdene for å fremheve bevegelse og form. Den etterlater håret friskt, fleksibelt og med et naturlig matt finish. Bruk den alene for en avslappet, undone look, eller som stylingbase før oppsett og føning for ekstra hold og tekstur.\r\n\r\nEgenskaper:\r\nGir umiddelbart volum og fylde\r\n\r\nFremhever tekstur og bevegelse\r\n\r\nLett formel med fleksibelt hold\r\n\r\nPerfekt til både løst hår og oppsetninger\r\n\r\nEtterlater ikke produktrester eller klissete følelse\r\n\r\nPasser alle hårtyper – spesielt fint eller flatt hår\r\n\r\nBruk:\r\nRist godt og spray i tørt hår ved røttene for volum, eller i lengdene for tekstur og hold. Style som ønsket.', 'stas', 'uploads/products/1762168879_stas5.webp', 1, 'active', '2025-11-04 10:11:27', '2025-11-04 10:52:21'),
(7, 'Stas Hair Filler', 'Opplev synlig fyldigere og sunnere hår med STAS Products Hairfiller – en avansert leave-in behandling utviklet for å styrke, beskytte og gi volum helt fra røttene. Denne lette, men kraftfulle formelen gir en umiddelbar følelse av tykkere hår samtidig som den jobber langsiktig med å forbedre hårkvaliteten.\r\n\r\nMed et konsentrert kompleks av aktive ingredienser stimulerer Hairfiller hodebunnen, støtter hårvekst og gir styrke til svakt eller skadet hår. Perfekt for deg som ønsker mer volum, bedre tekstur og en sunnere hårfølelse – uten å bruke tunge stylingprodukter.\r\n\r\nEgenskaper:\r\nGir umiddelbart synlig volum og fylde\r\n\r\nStyrker håret fra rot til spiss\r\n\r\nStimulerer og pleier hodebunnen\r\n\r\nLett og ikke-klissete leave-in behandling\r\n\r\nMotvirker hårtap og forbedrer hårstrukturen over tid\r\n\r\nPasser alle hårtyper, også fint eller skadet hår\r\n\r\nBruk:\r\nFordel produktet jevnt i hodebunnen og hårrøttene etter vask. Masser inn og style som vanlig – skal ikke skylles ut.', 'stas', 'uploads/products/1762168911_stas6.webp', 0, 'active', '2025-11-04 10:11:27', '2025-11-04 10:11:27'),
(8, 'Stas Dry Shampoo', 'STĀS Dry Shampoo er en effektiv tørrsjampo som gir håret en nyvasket følelse uten behov for vann. Den absorberer overflødig olje og urenheter, og etterlater håret friskt, lett og voluminøst – perfekt for hektiske dager, mellom hårvask eller etter trening.\r\n\r\nFordeler og egenskaper\r\nRask oppfriskning: Fjerner fett og urenheter, og gir håret en ren følelse på sekunder.\r\nVolumgivende: Tilfører naturlig volum og tekstur til håret.\r\nMild mot hodebunnen: Skånsom formel som passer for sensitiv hodebunn.\r\nPraktisk bruk: Enkel å bruke når du er på farten eller har begrenset tid.\r\nBruksanbefaling\r\nRist flasken godt før bruk.\r\nSpray jevnt på tørt hår, spesielt ved røttene, fra ca. 20 cm avstand.\r\nLa virke i noen sekunder, og masser lett inn i hodebunnen.\r\nBørst gjennom håret for å fordele produktet jevnt.\r\nIngredienser\r\nTapioca Starch: Naturlig stivelse som absorberer overflødig olje og gir volum.\r\nMagnesium Stearate: Bidrar til en jevn fordeling og forbedrer teksturen.\r\nPEG-12 Dimethicone: Gir en myk og silkeaktig følelse uten å tynge håret.\r\nParfum: Etterlater en frisk duft.\r\nHva gjør STĀS Dry Shampoo unik?\r\nSkånsom formel: Utviklet for å være mild mot hodebunnen, ideell for daglig bruk.\r\nVolumboost: Gir håret et løft og en fyldigere følelse uten å tynge.\r\nAllsidig: Passer for alle hårtyper og kan brukes når som helst på dagen.\r\nMålgruppe\r\nTravle personer: Perfekt for de som har en hektisk hverdag og trenger en rask håroppfriskning.\r\nTreningsentusiaster: Ideell etter trening for å fjerne svette og gi håret en frisk følelse.\r\nAlle hårtyper: Passer for både tynt og tykt hår, og kan brukes daglig.', 'stas', 'uploads/products/1762168939_stas7.webp', 0, 'active', '2025-11-04 10:11:27', '2025-11-04 10:11:27'),
(34, 'Reborn Repair Mask Keratin 250 ml', 'Reborn Repair Mask Keratin – intensiv hårkur for kjemisk og keratinbehandlet hår (250 ml)\r\n\r\nGi håret en dyptvirkende reparasjon med Reborn Repair Mask Keratin – en terapeutisk hårmaske spesielt utviklet for hår som har gjennomgått kjemiske behandlinger, inkludert keratinbehandlinger. Den unike formelen styrker og gjenoppretter hårfibrene samtidig som den pleier og beskytter.\r\n\r\nEgenskaper og fordeler\r\nRik på keratin, aminosyrer, kalsium og magnesium – hjelper med å gjenoppbygge skadet hår\r\n\r\nIntens fuktighet og elastisitet gjør håret mykere og mer medgjørlig\r\n\r\nReduserer porøsitet og gir en glatt, jevn overflate\r\n\r\nBalanserer pH-nivået i hårfibrene for bedre helse og styrke\r\n\r\nFri for natriumklorid, SLS og SLES – skånsom formel som ikke forstyrrer kjemiske behandlinger\r\n\r\nPasser spesielt godt for farget, bleket eller behandlet hår\r\n\r\nBruksanvisning\r\nVask håret grundig med sjampo\r\n\r\nKlem ut overflødig vann slik at håret er fuktig men ikke dryppende\r\n\r\nPåfør masken jevnt i lengder og tupper\r\n\r\nLa virke i 5–10 minutter\r\n\r\nMassér lett og skyll grundig med lunkent vann\r\n\r\nBruk 1–2 ganger i uken for vedlikehold og dyptvirkende pleie\r\n\r\nSpesifikasjoner\r\nVolum: 250 ml\r\n\r\nType: reparerende hårkur / maske\r\n\r\nEffekt: styrke, fukt, reparasjon, glatthet, elastisitet\r\n\r\nMålgruppe: hår som har vært utsatt for kjemiske behandlinger, farging, bleking eller retting', 'reborn', 'uploads/products/1763764575_re1.webp', 1, 'active', '2025-11-21 22:36:15', '2025-11-21 22:36:15'),
(35, 'Reborn Repair Shampoo Hyaluronic Acid Complex 500', 'Reborn Repair Shampoo Hyaluronic Acid Complex – reparerende og fuktgivende sjampo (500 ml)\r\n\r\nReborn Repair Shampoo Hyaluronic Acid Complex er en innovativ sjampo utviklet for hår som er kjemisk behandlet eller har vært utsatt for varme og slitasje. Den unike formelen kombinerer hyaluronsyre og hydrolysert keratin for å gi intensiv fukt, styrke og beskyttelse. Denne shampooen tilbyr en helhetlig behandling med flere positive effekter for håret og hodebunnen.\r\n\r\nEgenskaper og fordeler\r\nGjenoppbygger og styrker hårfibrene\r\n\r\nGir dyp hydrering med hyaluronsyre som absorberer og binder fukt\r\n\r\nReduserer frizz og uønsket volum\r\n\r\nFjerner skånsomt smuss og overflødig olje uten å strippe håret\r\n\r\nØker fleksibilitet og elastisitet i håret\r\n\r\nEtterlater håroverflaten jevn og gir naturlig glans\r\n\r\nBeskytter hårfarge og forbedrer fargens holdbarhet\r\n\r\nBruksanvisning\r\nFukt håret godt\r\n\r\nPåfør passende mengde sjampo, massér forsiktig inn i hodebunn og lengder\r\n\r\nLa virke et par minutter for optimal effekt\r\n\r\nSkyll grundig med lunkent vann\r\n\r\nGjenta ved behov\r\n\r\nTeknisk informasjon\r\nVolum: 500 ml\r\n\r\nType: reparerende sjampo\r\n\r\nEffekt: fuktighet, styrke, glans, anti-frizz\r\n\r\nPasser for: kjemisk behandlet, skadet, tørt eller fargebehandlet hår', 'reborn', 'uploads/products/1763764619_re2.webp', 1, 'active', '2025-11-21 22:36:59', '2025-11-21 22:36:59'),
(36, 'Reborn Keratin Repair Leave In Mask 250 ml', 'Reborn Keratin Repair Leave-In Mask 250 ml\r\n\r\nGjenopprett vitalitet og glans med Reborn Keratin Repair Leave-In Mask – en alt-i-ett leave-in-formel som styrker skadet hår, tilfører fukt og beskytter mot varmeverktøy. Denne masken krever ingen skylling, og passer perfekt som en hurtigkur i hverdagen.\r\n\r\nEgenskaper og fordeler\r\nReparasjon: Inneholder keratin som bidrar til å reparere og styrke hårstrå\r\n\r\nFukt og mykhet: Låser inn fuktighet slik at håret føles mykt, glatt og smidig\r\n\r\nBeskyttelse: Skaper et beskyttende lag mot varmeverktøy og ytre påvirkninger\r\n\r\nAnti-frizz: Reduserer krus og flyvehår\r\n\r\nEnkel å bruke: Leave-in-formel – ingen skylling nødvendig\r\n\r\nEgnet for alle hårtyper – spesielt effektivt på skadet, kjemisk behandlet eller tørt hår\r\n\r\nBruksanvisning\r\nRist flasken før bruk\r\n\r\nPåfør en liten mengde i håndflatene\r\n\r\nFordel jevnt i fuktig eller håndkletørt hår, konsentrert mot lengder og tupper\r\n\r\nStyle som ønsket – kan også brukes i tørt hår for glans og kontroll\r\n\r\nSpesifikasjoner\r\nVolum: 250 ml\r\n\r\nType: leave-in mask / kur\r\n\r\nEffekt: reparasjon, fukt, beskyttelse, glans\r\n\r\nPasser for: skadet, tørt, kjemisk behandlet hår', 'reborn', 'uploads/products/1763764648_re3.webp', 1, 'active', '2025-11-21 22:37:28', '2025-11-21 22:37:28'),
(37, 'Reborn Black Caviar Repair Conditioner 300 ml', 'Reborn Black Caviar Repair Conditioner – luksuriøs og nærende balsam (300 ml)\r\n\r\nGi håret intensiv pleie og glans med Reborn Black Caviar Repair Conditioner – en eksklusiv balsam utviklet for tørt, skadet og kjemisk behandlet hår. Med kaviarekstrakt, rike oljer og vitaminer styrker den hårfibrene fra rot til spiss og etterlater håret silkemykt og glansfullt.\r\n\r\nEgenskaper og fordeler\r\nReparerer og gjenoppbygger hårstrukturen med kaviarekstrakt rik på proteiner og omega-fettsyrer\r\n\r\nTilfører dyp fuktighet og næring med arganolje og macadamiaolje\r\n\r\nBeskytter håret mot miljømessig stress og ytre påkjenninger\r\n\r\nReduserer frizz, gjør håret mer håndterbart og gir speilblank glans\r\n\r\nBeroliger hodebunnen med naturlige planteekstrakter og vitamin B5\r\n\r\nParabenfri og trygg å bruke på farge- og keratinbehandlet hår\r\n\r\nBruksanvisning\r\nVask håret med sjampo og klem ut overflødig vann\r\n\r\nPåfør balsamen i lengder og tupper\r\n\r\nLa virke i 2–5 minutter\r\n\r\nSkyll grundig med lunkent vann\r\n\r\nSpesifikasjoner\r\nVolum: 300 ml\r\n\r\nType: reparerende balsam / conditioner\r\n\r\nEffekt: styrke, fukt, glans, beskyttelse\r\n\r\nPasser for: tørt, skadet, fargebehandlet og kjemisk behandlet hår', 'reborn', 'uploads/products/1763764678_re4.webp', 1, 'active', '2025-11-21 22:37:58', '2025-11-21 22:37:58'),
(38, 'Reborn Hair Smoothing Heat Protection 250 ml', 'Reborn Hair Smoothing Hyaluronic Acid Complex – lett leave-in spray med varmebeskyttelse (ca. 250 ml)\r\n\r\nOpplev et glatt, skinnende og beskyttet hår med Reborn Hair Smoothing Hyaluronic Acid Complex – en innovativ leave-in spray som kombinerer fukt, glans og termisk vern i ett produkt. Denne lette formelen danner en ultrafin hinne over hårfibrene som, når aktivert med varme fra føner, gir et silkemykt og langvarig sløret utseende.\r\n\r\nEgenskaper og fordeler\r\nSkaper silkeaktig glans og glatt tekstur\r\n\r\nInneholder hyaluronsyre som tilfører dyp fukt og elastisitet\r\n\r\nBeskytter mot varmeskader – bevarer hårkvaliteten ved bruk av stylingverktøy\r\n\r\nLett leave-in spray – tynger ikke ned håret\r\n\r\nLangvarig effekt som varer i flere dager uten at håret mister utseendet\r\n\r\nIdeell for deg som ønsker både pleie og funksjon i én stylingløsning\r\n\r\nBruksanvisning\r\nVask og klem ut fukt fra håret\r\n\r\nSpray produktet jevnt over hele håret (fra røtter til tupper)\r\n\r\nMassér lett gjennom for å fordele\r\n\r\nFøn håret og style som normalt\r\n\r\nHar du brukt varmeverktøy – produktets varmebeskyttelse aktiveres og resultatet forlenges\r\n\r\nSpesifikasjoner\r\nVolum: ca. 250 ml\r\n\r\nProduktform: leave-in spray\r\n\r\nEffekt: fukt, varmebeskyttelse, glatthet og glans\r\n\r\nPasser for: alle hårtyper – spesielt skadet, krusete eller varmebehandlet hår', 'reborn', 'uploads/products/1763764734_re5.webp', 1, 'active', '2025-11-21 22:38:54', '2025-11-21 22:38:54'),
(39, 'Reborn Amino Silk Repair Shampoo 400 ml', 'Reborn Amino Silk Repair Shampoo – reparerende og fuktgivende sjampo (400 ml)\r\n\r\nGi nytt liv til skadet og tørt hår med Reborn Amino Silk Repair Shampoo. Denne profesjonelle sjampoen er utviklet for å gjenopprette hårfibrene i dybden og tilføre intens pleie uten å tynge. Den er sulfatfri og skånsom, perfekt for daglig bruk og for hår som er kjemisk behandlet eller rettet.\r\n\r\nEgenskaper og fordeler\r\nReparerer og styrker skadet hår\r\n\r\nTilfører intens fuktighet og gjør håret mykt og smidig\r\n\r\nBeriket med aminosyrer, pro-vitamin B5 og sukkerkompleks for maksimal pleie\r\n\r\nØker elastisitet og reduserer risiko for brekkasje\r\n\r\nFremhever naturlig glans uten å tynge\r\n\r\nSulfatfri og skånsom formulering\r\n\r\nBruksanvisning\r\nFukt håret grundig\r\n\r\nPåfør en passende mengde og massér forsiktig inn i hodebunn og lengder\r\n\r\nSkyll grundig\r\n\r\nGjenta ved behov\r\n\r\nSpesifikasjoner\r\nVolum: 400 ml\r\n\r\nType: reparerende sjampo\r\n\r\nEffekt: fuktighet, gjenoppbygging, glans og styrke\r\n\r\nAnbefalt for: skadet, tørt eller kjemisk behandlet hår\r\n\r\n', 'reborn', 'uploads/products/1763764770_re6.webp', 1, 'active', '2025-11-21 22:39:30', '2025-11-21 22:39:30'),
(40, 'Reborn Repair Mask Keratin 50 ml', 'Reborn Repair Mask Keratin – intensiv hårkur for kjemisk og keratinbehandlet hår (50 ml)\r\n\r\nGi håret en dyptvirkende reparasjon med Reborn Repair Mask Keratin – en terapeutisk hårmaske spesielt utviklet for hår som har gjennomgått kjemiske behandlinger, inkludert keratinbehandlinger. Den unike formelen styrker og gjenoppretter hårfibrene samtidig som den pleier og beskytter.\r\n\r\nEgenskaper og fordeler\r\nRik på keratin, aminosyrer, kalsium og magnesium – hjelper med å gjenoppbygge skadet hår\r\n\r\nIntens fuktighet og elastisitet gjør håret mykere og mer medgjørlig\r\n\r\nReduserer porøsitet og gir en glatt, jevn overflate\r\n\r\nBalanserer pH-nivået i hårfibrene for bedre helse og styrke\r\n\r\nFri for natriumklorid, SLS og SLES – skånsom formel som ikke forstyrrer kjemiske behandlinger\r\n\r\nPasser spesielt godt for farget, bleket eller behandlet hår\r\n\r\nBruksanvisning\r\nVask håret grundig med sjampo\r\n\r\nKlem ut overflødig vann slik at håret er fuktig men ikke dryppende\r\n\r\nPåfør masken jevnt i lengder og tupper\r\n\r\nLa virke i 5–10 minutter\r\n\r\nMassér lett og skyll grundig med lunkent vann\r\n\r\nBruk 1–2 ganger i uken for vedlikehold og dyptvirkende pleie\r\n\r\nSpesifikasjoner\r\nVolum: 50 ml\r\n\r\nType: reparerende hårkur / maske\r\n\r\nEffekt: styrke, fukt, reparasjon, glatthet, elastisitet\r\n\r\nMålgruppe: hår som har vært utsatt for kjemiske behandlinger, farging, bleking eller retting', 'reborn', 'uploads/products/1763945903_rere9.webp', 0, 'active', '2025-11-21 22:40:02', '2025-11-24 00:58:23'),
(41, 'Reborn Black Mud Healing Mask 250 ml', 'Reborn Black Mud Healing Mask – mineralrik hårkur for dyp reparasjon (250 ml)\r\n\r\nGjenoppliv hårets glans og vitalitet med Reborn Black Mud Healing Mask – en luksuriøs hårkur utviklet med 26 mineraler fra Dødehavet. Denne masken gir intensiv næring, lindring til hodebunn og styrke til hårrøttene, slik at håret fremstår smidig, balansert og full av liv.\r\n\r\nEgenskaper og fordeler\r\nMineralrik hårmaske med svart leire som nærer dypt\r\n\r\nLindrer kløe og irritasjon i hodebunnen, gir komfort og balanse\r\n\r\nStimulerer mikrosirkulasjon og styrker hårvekst\r\n\r\nReparerer skader, øker elastisitet og gir motstandskraft\r\n\r\nEtterlater håret mykt, glatt og med en sunn glans\r\n\r\nBruksanvisning\r\nVask håret med en passende sjampo og klem ut overflødig vann\r\n\r\nPåfør masken generøst i lengder og hodebunn\r\n\r\nMassér lett og la virke i 5 minutter (for ekstra effekt, bruk varmt håndkle)\r\n\r\nSkyll grundig med lunkent vann\r\n\r\nSpesifikasjoner\r\nVolum: 250 ml\r\n\r\nType: helbredende / reparerende hårmaske\r\n\r\nEffekt: dyp næring, reparasjon, hodebunnslindring, fukt, glans\r\n\r\nMålgruppe: tørt, skadet, kjemisk behandlet hår med behov for ekstra pleie', 'reborn', 'uploads/products/1763945372_rere1.webp', 1, 'active', '2025-11-21 22:40:38', '2025-11-24 00:49:32'),
(42, 'Reborn Black Mud Shampoo–Healing Shampoo 500 ml', 'Reborn Black Mud Shampoo – helbredende mineralrik sjampo (500 ml)\r\n\r\nGi hår og hodebunn kraftig pleie og fornyelse med Reborn Black Mud Shampoo – en dyprensende, mineralbasert formel med ekte svart leire fra Dødehavet. Denne luksuriøse sjampoen styrker hårrøttene, balanserer hodebunnen og etterlater håret mykt, glansfullt og vitalt.\r\n\r\nEgenskaper og fordeler\r\nMineralrik sjampo med 26 mineraler som gir næring til hårrøttene\r\n\r\nHelbredende effekt som lindrer kløe, irritation og tørrhet i hodebunnen\r\n\r\nStimulerer hårvekst og forbedrer hårstruktur og elastisitet\r\n\r\nSkånsom, pH-balansert rens som fjerner urenheter uten å skade håret\r\n\r\nEtterlater håret mykt, smidig og med naturlig glans\r\n\r\nEgnet for alle hårtyper, spesielt for sensitiv eller skadet hodebunn\r\n\r\nBruksanvisning\r\nFukt håret grundig\r\n\r\nPåfør ønsket mengde sjampo i hodebunn og lengder\r\n\r\nMassér godt med fingertuppene for å aktivere mineralene\r\n\r\nSkyll grundig med lunkent vann\r\n\r\nGjenta hvis nødvendig\r\n\r\nFor maksimal behandlingseffekt, bruk gjerne sammen med Reborn Black Mud Mask\r\n\r\nSpesifikasjoner\r\nVolum: 500 ml\r\n\r\nType: helbredende / mineralrik sjampo\r\n\r\nEffekt: rens, næring, lindring, styrke og glans\r\n\r\nPasser for: tørr, irritert, skadet eller sensitiv hodebunn', 'reborn', 'uploads/products/1763945671_rere5.webp', 0, 'active', '2025-11-21 22:42:40', '2025-11-24 00:54:31'),
(43, 'Reborn Black Mud Shampoo–Healing Shampoo 300 ml', 'Reborn Black Mud Shampoo – mineralrik, helbredende sjampo med dødehavsmudder (300 ml)\r\n\r\nOpplev en luksuriøs hårpleieopplevelse med Reborn Black Mud Shampoo – en helbredende, mineralrik sjampo med ekte svart leire fra Dødehavet. Denne profesjonelle sjampoen er skapt for å gi dyp rens, næring og reparasjon til både hår og hodebunn. Perfekt for deg som ønsker et sterkere, sunnere og mer glansfullt hår.\r\n\r\nEgenskaper og fordeler\r\nMineralrik sjampo med dødehavsmudder – gir intensiv rens og pleie\r\n\r\nLindrer tørr, irritert og sensitiv hodebunn\r\n\r\nStimulerer hårvekst og styrker hårrøttene\r\n\r\nGir mykt, glatt og glansfullt hår uten å tynge\r\n\r\nReparerende og fuktighetsgivende sjampo for skadet hår\r\n\r\npH-balansert formel som beskytter mot varme og ytre påkjenninger\r\n\r\nProfesjonell hårpleie tilpasset både menn og kvinner\r\n\r\nBruksanvisning\r\nFukt håret godt og påfør en liten mengde sjampo\r\n\r\nMassér inn i hodebunn og lengder for å aktivere de helbredende mineralene\r\n\r\nSkyll grundig og gjenta ved behov\r\n\r\nFor best resultat – kombiner med Reborn Black Mud Mask\r\n\r\nSpesifikasjoner\r\nVolum: 300 ml\r\n\r\nType: mineralrik og helbredende sjampo\r\n\r\nEffekt: rens, styrke, lindring, glans\r\n\r\nPasser for: tørt, skadet, sensitivt eller kjemisk behandlet hår', 'reborn', 'uploads/products/1763945611_rere3.webp', 0, 'active', '2025-11-21 22:43:41', '2025-11-24 00:53:31'),
(44, 'Reborn Smoothing Conditioner 500 ml', 'Reborn Smoothing Conditioner – intensiv mykgjøring og glans (500 ml)\r\n\r\nGi håret luksuriøs omsorg med Reborn Smoothing Conditioner 500 ml – en kraftfull balsam utviklet spesielt for tørt, skadet og krusete hår. Den avanserte formelen kombinerer hyaluronsyre, keratin og arganolje for å tilføre dyp fuktighet, reparere strukturer og redusere frizz, mens håret bevares lett og levende.\r\n\r\nEgenskaper og fordeler\r\nDyptvirkende fukt og mykgjøring – gjør håret silkemykt\r\n\r\nReduserer frizz og gir en jevnere, mer håndterbar tekstur\r\n\r\nStyrker hårfibrene og øker motstandskraft\r\n\r\nBevarer glans og forbedrer hårstruktur\r\n\r\nSkånsom nok for daglig bruk, tilpasset kjemisk behandlet hår\r\n\r\nBruksanvisning\r\nBruk etter Reborn Smoothing Shampoo\r\n\r\nPåfør balsamen i håndkletørt hår – fra midtlengder til tupper (unngå hårbunn)\r\n\r\nLa virke i 2–3 minutter\r\n\r\nSkyll grundig med lunkent vann\r\n\r\nBruk 1–2 ganger per uke for intensiv pleie\r\n\r\nSpesifikasjoner\r\nVolum: 500 ml\r\n\r\nType: glattende og mykgjørende balsam\r\n\r\nEffekt: fukt, reparasjon, glans, anti-frizz\r\n\r\nMålgruppe: tørt, skadet, krusete eller behandlet hår', 'reborn', 'uploads/products/1763945445_rere2.webp', 1, 'active', '2025-11-21 22:44:16', '2025-11-24 00:50:45'),
(45, 'Reborn Smoothing Shampoo 500 ml', 'Reborn Smoothing Shampoo – mykgjørende og anti-frizz sjampo (500 ml)\r\n\r\nGi håret en luksuriøs behandling med Reborn Smoothing Shampoo 500 ml, spesielt utviklet for tørt, krusete og kjemisk behandlet hår. Denne kraftfulle formelen kombinerer hyaluronsyre og keratin for å fukte dypt, reparere skader og redusere frizz, samtidig som den bevarer glatthet og glans.\r\n\r\nEgenskaper og fordeler\r\nReduserer krus og uønsket volum\r\n\r\nTilfører intens fuktighet uten å tynge håret\r\n\r\nStyrker hårfibrene og forbedrer elastisitet\r\n\r\nSkaper en jevn og glatt overflate\r\n\r\nBidrar til å bevare farge og beskytte mot slitasje\r\n\r\nSkånsom og mild formel — egnet for jevnlig bruk\r\n\r\nBruksanvisning\r\nFukt håret godt\r\n\r\nPåfør sjampo i hodebunn og lengder, og massér til skum\r\n\r\nLa virke i 1–2 minutter for dypere påvirkning\r\n\r\nSkyll grundig med lunkent vann\r\n\r\nFor best effekt, bruk sammen med Reborn Smoothing Conditioner og mask\r\n\r\nSpesifikasjoner\r\nVolum: 500 ml\r\n\r\nType: smoothing / anti-frizz sjampo\r\n\r\nEffekt: fuktighet, reparasjon, mykhet, glans\r\n\r\nPasser for: tørt, krusete, kjemisk behandlet hår', 'reborn', 'uploads/products/1763946094_rere12.webp', 0, 'active', '2025-11-21 22:44:48', '2025-11-24 01:01:34'),
(46, 'Reborn Smoothing Serum 50 ml', 'Reborn Smoothing Serum – glatt, skinnende og frizz-fri finish (50 ml)\r\n\r\nGi håret en silkemyk behandling med Reborn Smoothing Serum – en avansert leave-in formel utviklet for å målrette skader fra varmeverktøy og redusere krus uten å tynge håret. Denne lette og effektive serumblandingen kombinerer hyaluronsyre og keratin for dyp fukt og reparasjon gjennom hele hårstrået.\r\n\r\nEgenskaper og fordeler\r\nGjendanner glatt tekstur og eliminerer uønsket frizz\r\n\r\nIntens fuktgivende effekt som gjør håret mykt og skinnende\r\n\r\nBeskytter mot skade fra varmeverktøy som føner og rettetang\r\n\r\nAbsorberes hurtig – etterlater ingen fet eller tung følelse\r\n\r\nOptimalisert for daglig bruk i alle hårtyper som ønsker glatthet og kontroll\r\n\r\nBruksanvisning\r\nPå vått hår: Etter vask og håndkle­tørking – påfør en liten mengde i håndflatene, fordel i lengder og tupper, og style som ønsket.\r\nPå tørt hår: Bruk litt serum i håndflatene og massér forsiktig inn i lengder og spisser for å kontrollere flyvehår, tilføre glans og definisjon.\r\n\r\nSpesifikasjoner\r\nVolum: 50 ml\r\n\r\nType: leave-in serum\r\n\r\nEffekt: glatting, fuktighetsgivende, anti-frizz, varmebeskyttelse\r\n\r\nPasser for: tørt, skadet, krusete hår eller hår som utsettes for varmeverktøy', 'reborn', 'uploads/products/1763945981_rere10.webp', 0, 'active', '2025-11-21 22:45:32', '2025-11-24 00:59:41'),
(47, 'Reborn Amino Silk Repair Mask 250 ml', 'Reborn Amino Silk Repair Mask – intensiv hårkur for skadet hår (250 ml)\r\n\r\nReduser slitasje og gi håret ny vitalitet med Reborn Amino Silk Repair Mask. Denne kraftige hårkuren er spesielt utviklet for farget, bleket eller kjemisk behandlet hår som trenger dyptgående reparasjon. Masken kombinerer sericin (silkeprotein), aminosyrer og fuktgivende ingredienser for å styrke hårfibrene innenfra og tilføre langsiktig mykhet og glans.\r\n\r\nEgenskaper og fordeler\r\nGjenoppbygger hårstruktur og styrker skadet hår\r\n\r\nReduserer frizz og gjør håret jevnere og mer håndterbart\r\n\r\nTilfører intensiv fukt og mykgjøring uten å tynge\r\n\r\nBevarer farge og gir økt glans\r\n\r\nVirker effektivt på fargebehandlet, falmet eller sprøtt hår\r\n\r\nBruksanvisning\r\nVask håret med en egnet sjampo og klem ut overflødig vann\r\n\r\nPåfør masken jevnt i lengder og tupper\r\n\r\nLa masken virke i 5–15 minutter (etter behov)\r\n\r\nSkyll grundig med lunkent vann\r\n\r\nBruk 1–2 ganger i uken som en del av hårpleierutinen\r\n\r\nSpesifikasjoner\r\nVolum: 250 ml\r\n\r\nType: intensiv reparerende hårkur / mask\r\n\r\nEffekt: styrke, reparasjon, fukt, glans og anti-frizz\r\n\r\nPasser for: skadet, kjemisk behandlet, bleket eller tørt hår\r\n\r\nTilfører dyp fuktighet og næring for mykere hår\r\n\r\nBevarer hårfargen og gir økt glans\r\n\r\nSkånsom og effektiv formel som passer alle hårtyper\r\n\r\nBruksanvisning\r\nVask håret med sjampo og skyll godt.\r\n\r\nKlem ut overflødig vann slik at håret er fuktig.\r\n\r\nPåfør en passende mengde maske i lengder og tupper.\r\n\r\nLa virke i 5–15 minutter, avhengig av hårets behov.\r\n\r\nSkyll grundig med lunkent vann.\r\n\r\nBruk 1–2 ganger i uken eller ved behov for ekstra pleie.\r\n\r\nPasser for\r\nSkadet, tørt eller kjemisk behandlet hår\r\n\r\nFarget hår som trenger ekstra glans og beskyttelse\r\n\r\nHår med frizz eller grov tekstur\r\n\r\nProfesjonell salongbruk og hjemmepleie', 'reborn', 'uploads/products/1763765179_re14.webp', 0, 'active', '2025-11-21 22:46:19', '2025-11-21 22:46:19'),
(48, 'Reborn Amino Silk Leave-In 250 ml', 'Reborn Amino Silk Leave-In – intensiv leave-in krem for fukt, mykhet og glans (250 ml)\r\n\r\nOpplev forvandlingen med Reborn Amino Silk Leave-In, en alt-i-ett leave-in krem utviklet for å dempe frizz, tilføre dyptgående fukt og skape en strålende glans i alle hårtyper – spesielt egnet for farget, skadet eller kjemisk behandlet hår.\r\n\r\nEgenskaper og fordeler\r\nReduserer frizz og gir en jevn, glatt hårstruktur\r\n\r\nTilfører intens fuktighet og mykgjør uten å tynge\r\n\r\nStyrker håret ved hjelp av aminosyrer, sericin og pro-vitamin B5\r\n\r\nBeskytter mot varmeverktøy ved styling\r\n\r\nHoldbar og lett konsistens – ideell for daglig bruk\r\n\r\nØker elastisitet og glans, samtidig som håret blir mer håndterbart\r\n\r\nBruksanvisning\r\nVask og klem ut fukt fra håret\r\n\r\nTa noen pump eller dusjproteiner i håndflatene\r\n\r\nFordel jevnt i mellom lengder og tupper\r\n\r\nStyle som ønsket – kan brukes før føning eller i tørt hår for glans og kontroll\r\n\r\nSpesifikasjoner\r\nVolum: 250 ml\r\n\r\nType: leave-in krem / behandling\r\n\r\nEffekt: fukt, reparasjon, glans, frizz-kontroll, beskyttelse\r\n\r\nAnbefales for: farget, skadet, tørt hår eller profesjonell pleiebehov', 'reborn', 'uploads/products/1763765208_re15.webp', 0, 'active', '2025-11-21 22:46:48', '2025-11-21 22:46:48'),
(49, 'Reborn Black Caviar Repair Shampoo 300 ml', 'Skånsom rens og dyp reparasjon for tørt og skadet hår\r\n\r\nRe-Born Black Caviar Repair Shampoo er en luksuriøs, næringsrik sjampo designet for å gjenopprette balansen i tørt, slitt og kjemisk behandlet hår. Den er beriket med proteinrikt kaviarekstrakt, pleiende oljer og fuktighetsgivende planteekstrakter som gir både reparasjon og glans – uten å tynge.\r\n\r\nFordeler\r\n\r\nGjenoppbygger og styrker skadet hår\r\nRenser skånsomt uten å tørke ut\r\nTilfører fuktighet og glans\r\nBeskytter mot miljøskader og frie radikaler\r\nParabenfri og trygg for fargebehandlet og keratinbehandlet hår\r\nPasser for\r\n\r\nTørt, sprøtt eller livløst hår\r\nHår som er bleket, farget eller kjemisk behandlet\r\nHår som trenger styrke, fukt og glans i én og samme vask\r\nAktive ingredienser\r\n\r\nSvart kaviarekstrakt – Rik på proteiner og omega-fettsyrer som reparerer og styrker\r\nArgan- og macadamiaolje – Gir næring, smidighet og glans\r\nGranateple- og appelsinekstrakter – Antioksidanter som beskytter håret\r\nAloe vera, kamille og vitamin B5 – Lindrer hodebunnen og tilfører fukt\r\nMineraler fra Dødehavet – Bidrar til revitalisering av hår og hodebunn\r\nBruksanvisning\r\n\r\nPåfør i vått hår og massér forsiktig inn i hodebunn og lengder. Skyll grundig og gjenta ved behov. For best resultat, bruk sammen med Re-Born Black Caviar Repair Conditioner.\r\n\r\nVekt: 300ml', 'reborn', 'uploads/products/1763765237_re16.webp', 0, 'active', '2025-11-21 22:47:17', '2025-11-21 22:47:17'),
(50, 'Reborn Texturizing Wave Mousse 150 ml', 'Reborn Texturizing Wave Mousse – lett mousse for volum, tekstur og definisjon (150 ml)\r\n\r\nGi håret liv, bevegelse og definert struktur med Reborn Texturizing Wave Mousse. Denne luksuriøse mousse-formelen er utviklet for å fremheve bølger og krøller uten å gjøre håret stivt eller klebrig. Den er fri for alkohol, olje og salt, og fungerer som et effektivt anti-frizz-produkt som tilfører volum og tekstur — alt i ett.\r\n\r\nEgenskaper og fordeler\r\nFremhever og definerer naturlige bølger og krøller\r\n\r\nBygger volum med en lett, fleksibel finish\r\n\r\nReduserer frizz og statisk elektrisitet\r\n\r\nAlkoholfri, olje- og saltfri formulering\r\n\r\nLangvarig effekt uten at håret føles tungt\r\n\r\nPasser fint hår som trenger tekstur, og krøllete hår som ønsker kontroll\r\n\r\nBruksanvisning\r\nRist flasken godt før bruk.\r\n\r\nPåfør ønsket mengde i fuktig hår, fra røttene til tuppene.\r\n\r\nKlem frem bølger med hendene, eller bruk en diffuser for ekstra volum.\r\n\r\nLa håret lufttørke eller føn for raskere tørketid og definert finish.\r\n\r\nSpesifikasjoner\r\nVolum: 150 ml\r\n\r\nType: tekstur- og volumgivende mousse\r\n\r\nEffekt: definisjon, volum, anti-frizz\r\n\r\nIdeell for: bølgete, krøllete, fint eller livløst hår', 'reborn', 'uploads/products/1763765302_re17.webp', 0, 'active', '2025-11-21 22:48:22', '2025-11-21 22:48:22'),
(51, 'Reborn Smoothing Mask 250 ml', 'ReBorn Smoothing Mask – intensiv maskekur for glatt og styrket hår (250 ml)\r\n\r\nGi håret en dypere reparasjon med ReBorn Smoothing Mask – en luksuriøs hårkur skreddersydd for tørt, krusete eller kjemisk behandlet hår. Denne masken hjelper med å gjenopprette struktur, låse inn fukt og redusere frizz, slik at håret fremstår mykere, glattere og mer motstandsdyktig mot ytre påvirkninger.\r\n\r\nEgenskaper og fordeler\r\nDyptvirkende reparasjon for skadet og sprøtt hår\r\n\r\nTilfører intens fuktighet og glans uten å tynge\r\n\r\nReduserer krus og gjør håret mer håndterlig\r\n\r\nForbedrer elastisitet og styrker hårfibrene\r\n\r\nIdeell som ukentlig behandling for å vedlikeholde glatthet og struktur\r\n\r\nBruksanvisning\r\nVask håret grundig og klem ut overflødig vann\r\n\r\nPåfør masken jevnt i lengder og tupper\r\n\r\nLa virke i 3–10 minutter, avhengig av hårtilstand\r\n\r\nSkyll grundig med lunkent vann\r\n\r\nBruk 1–2 ganger i uken for optimal effekt\r\n\r\nSpesifikasjoner\r\nVolum: 250 ml\r\n\r\nType: hårmaske / kur\r\n\r\nEffekt: reparasjon, fuktighet, glans, anti-frizz\r\n\r\nBruksområde: tørt, skadet eller behandlet hår', 'reborn', 'uploads/products/1763765326_re18.webp', 0, 'active', '2025-11-21 22:48:46', '2025-11-21 22:48:46'),
(52, 'Reborn Smoothing Conditioner 300 ml', 'ReBorn Smoothing Conditioner – silkemyk og glansgivende balsam (300 ml)\r\n\r\nLa håret oppleve luksuriøs pleie med ReBorn Smoothing Conditioner – en intensiv balsam spesielt skapt for tørt, krusete og skadet hår. Denne konsentrerte formuleringen kombinerer keratin og hyaluronsyre med ernæringsrike oljer som arganolje for å gi dypt virkende reparasjon og en glatt, jevn finish på bare minutter.\r\n\r\nEgenskaper og fordeler\r\nReduserer krus og gir en mykere, mer håndterbar tekstur\r\n\r\nTilfører intens fukt og næring uten å tynge håret\r\n\r\nStyrker og reparerer hårfibrene, og bidrar til bedre elastisitet\r\n\r\nØker glansen og forbedrer den visuelle kvaliteten på håret\r\n\r\nVirker raskt – optimal virketid på tre minutter\r\n\r\nVelegnet til daglig bruk for alle hårtyper som ønsker jevnhet og glans\r\n\r\nBruksanvisning\r\nVask håret grundig med en skånsom shampoo\r\n\r\nPress ut overflødig vann\r\n\r\nPåfør balsamen jevnt fra midtlengder til tupper\r\n\r\nLa virke i ca. 3 minutter\r\n\r\nSkyll grundig med lunkent vann\r\n\r\nSpesifikasjoner\r\nVolum: 300 ml\r\n\r\nType: balsam / conditioner\r\n\r\nEffekt: fukt, reparasjon, mykhet, anti-frizz\r\n\r\nPasser for: tørt, krusete, skadet eller kjemisk behandlet hår', 'reborn', 'uploads/products/1763765352_re19.webp', 0, 'active', '2025-11-21 22:49:12', '2025-11-21 22:49:12'),
(53, 'Reborn Smoothing Shampoo 300 ml', 'ReBorn Smoothing Shampoo – anti-frizz og reparasjon for glatt og mykt hår (300 ml)\r\n\r\nGi håret intens pleie og kontroll med ReBorn Smoothing Shampoo 300 ml. Denne avanserte formelen er spesielt utviklet for hår med tendens til krus og skader — en unik blanding av hyaluronsyre, keratin og pleiende ingredienser gir deg en myk, glatt og strålende finish.\r\n\r\nEgenskaper og fordeler\r\nReduserer frizz og uønskede luftlag for et jevnere hår\r\n\r\nTilfører intens fuktighet, som gjør håret mykere og mer smidig\r\n\r\nReparerer og styrker hårfibrene for økt elastisitet og vitalitet\r\n\r\nForbedrer glans og kropp, samtidig som håret bevares lett og naturlig\r\n\r\nMild og skånsom formulering – egnet for hyppig bruk og daglige rutiner\r\n\r\nBruksanvisning\r\nFukt håret godt\r\n\r\nPåfør shampoo i hodebunn og lengder, massér til skum\r\n\r\nLa virke én til to minutter om ønskelig\r\n\r\nSkyll grundig med lunkent vann\r\n\r\nFor best resultat, følg opp med ReBorn Smoothing Conditioner eller Smoothing Mask\r\n\r\nSpesifikasjoner\r\nVolum: 300 ml\r\n\r\nType: glans- og anti-frizz sjampo\r\n\r\nEffekt: fuktighet, reparasjon, mykgjøring, frizz-kontroll\r\n\r\nPasser for: tørt, krusete, skadet eller varmebehandlet hår\r\n\r\n', 'reborn', 'uploads/products/1763946028_rere11.webp', 0, 'active', '2025-11-21 22:49:37', '2025-11-24 01:00:28'),
(54, 'Reborn Blonde Highlight Conditioner 500 ml', 'ReBorn Blonde Highlight Conditioner – reparerende balsam for blondt og stripet hår (500 ml)\r\n\r\nGi ditt blonde, blekede eller stripede hår optimal pleie med ReBorn Blonde Highlight Conditioner. Denne fiolettpigmenterte balsamen beskytter fargen, styrker hårfiberne og tilfører dyp fuktighet slik at håret forblir mykt, glansfullt og velpleid.\r\n\r\nEgenskaper og fordeler\r\nNøytraliserer uønskede varme toner – demper gule og oransje nyanser\r\n\r\nInneholder keratin og hyaluronsyre som gjenskaper styrke og elastisitet\r\n\r\nBeriket med hvetekim og havtornolje (Obliphica) for næring og mykgjøring\r\n\r\nFuktgivende og reparerende – bidrar til å redusere frizz og forbedre hårstruktur\r\n\r\nLett formel som ikke tynger håret – ideell for daglig bruk\r\n\r\nBruksanvisning\r\nVask håret med en fargebevarende sjampo\r\n\r\nPåfør balsamen i håndkletørt hår, fra midten og ned mot tuppene\r\n\r\nLa virke i 1–3 minutter\r\n\r\nSkyll godt med lunkent vann\r\n\r\nBruk 1–2 ganger per uke som vedlikeholdskur\r\n\r\nSpesifikasjoner\r\nVolum: 500 ml\r\n\r\nType: fargebevarende balsam\r\n\r\nEffekt: fargebeskyttelse, reparasjon, fuktighet, glans\r\n\r\nAnbefalt for: farget, stripet, bleket eller hår med varme toner', 'reborn', 'uploads/products/1763765408_re21.webp', 0, 'active', '2025-11-21 22:50:08', '2025-11-21 22:50:08'),
(55, 'Reborn Blonde Highlight Shampoo 500 ml', 'Blonde Highlight Shampoo – fiolett pigmentert sjampo for bleket og blondt hår (500 ml)\r\n\r\nGi håret en målrettet behandling med Blonde Highlight Shampoo 500 ml – en pigmentert shampoo spesielt formulert for stripet, bleket og blondt hår. Denne fiolette sjampoen hjelper med å balansere varme nyanser, beskytte tonen og samtidig tilføre fukt og glans.\r\n\r\nEgenskaper og fordeler\r\nNøytraliserer gule og oransje toner for en klarere, kaldere hårfarge\r\n\r\nSkånsom rens som bevarer hårstruktur og farge\r\n\r\nFormulert med fuktgivende ingredienser som mykgjør og styrker\r\n\r\nBidrar til å bevare glans, silkemyk tekstur og frisk utstråling\r\n\r\nPasser for regelmessig bruk – ideell for vedlikehold av blond og tonet hår\r\n\r\nBruksanvisning\r\nFukt håret godt med lunkent vann\r\n\r\nPåfør en passende mengde i hodebunn og lengder\r\n\r\nMassér forsiktig inn og la virke i 1-3 minutter\r\n\r\nSkyll grundig\r\n\r\nGjenta kun ved behov\r\n\r\nKombiner gjerne med matching conditioner eller maske for best resultat\r\n\r\nSpesifikasjoner\r\nVolum: 500 ml\r\n\r\nType: fiolett shampoo for blondt og bleket hår\r\n\r\nEffekt: tonekorrigering, fargebeskyttelse, fuktighet og glans\r\n\r\nPasser til: blondt, bleket eller stripet hår', 'reborn', 'uploads/products/1763765437_re22.webp', 0, 'active', '2025-11-21 22:50:37', '2025-11-21 22:50:37'),
(56, 'Reborn Blonde Highlight Serum 50 ml', 'ReBorn Blonde Highlight Serum – leave-in behandling for blondt og bleket hår (50 ml)\r\n\r\nOpplev et lysere, sunnere og mer strålende hår med ReBorn Blonde Highlight Serum. Dette lette leave-in-serumet er spesielt utviklet for blondt, stripet og kjemisk behandlet hår. Det gir intensiv pleie, demper frizz og beskytter fargepigmentene – uten å tynge.\r\n\r\nEgenskaper og fordeler\r\nNøytraliserer varme toner i lyst eller bleket hår\r\n\r\nTilfører intensiv fukt og glans samtidig som det styrker hårfibrene\r\n\r\nReduserer krus og gjør håret mykt og lett å style\r\n\r\nLeave-in – trenger ikke skylles ut\r\n\r\nIdeell for daglig bruk eller som «touch-up» mellom vasker\r\n\r\nBruksanvisning\r\nVask og tørk håret lett med håndkle\r\n\r\nTa noen dråper serum i håndflatene\r\n\r\nFordel i lengder og tupper\r\n\r\nStyle som ønsket – kan også brukes i tørt hår for glans og kontroll\r\n\r\nSpesifikasjoner\r\nVolum: 50 ml\r\n\r\nType: leave-in hårserum\r\n\r\nEffekt: fuktighet, definisjon, fargebeskyttelse, anti-frizz\r\n\r\nPasser for: blondt, stripet og bleket hår\r\n\r\n', 'reborn', 'uploads/products/1763765464_re23.webp', 0, 'active', '2025-11-21 22:51:04', '2025-11-21 22:51:04'),
(57, 'Reborn Blond Hightlight Mask 250 ml', 'ReBorn Blonde Highlight Mask – intensiv kur for blondt og stripet hår (250 ml)\r\n\r\nGi håret ekstra kjærlighet med ReBorn Blonde Highlight Mask – en kraftfull, fiolett pigmentert hårmaske som nøytraliserer varme toner og gjenoppretter glans og vitalitet. Denne masken er spesielt utviklet for bleket, stripet og lyst hår som trenger dyp pleie og fargebevaring.\r\n\r\nEgenskaper og fordeler\r\nNøytraliserer gule og oransje nyanser og gjenoppretter kalde toner\r\n\r\nReker hårfibrene med keratin og hyaluronsyre for økt styrke\r\n\r\nGir intens fuktighet og mykhet uten å tynge håret\r\n\r\nDemper frizz og gir glatt, jevn overflate\r\n\r\nBeskytter mot falming og slitasje\r\n\r\nIdeell som ukentlig kur for å vedlikeholde farge og struktur\r\n\r\nAnvendelse\r\nVask håret med en fiolett eller fargebevarende sjampo\r\n\r\nPress ut overflødig vann fra håret\r\n\r\nPåfør masken jevnt i lengder og tupper\r\n\r\nLa virke i 3–5 minutter, eller lenger ved behov\r\n\r\nSkyll grundig med lunkent vann\r\n\r\nSpesifikasjoner\r\nVolum: 250 ml\r\n\r\nType: intensiv hårkur / mask\r\n\r\nEffekt: fargekorrigering, fuktighet, reparasjon, dempet frizz\r\n\r\nPasser for: bleket, stripet eller blondt hår', 'reborn', 'uploads/products/1763765489_re24.webp', 0, 'active', '2025-11-21 22:51:29', '2025-11-21 22:51:29'),
(58, 'Reborn Blonde Highlight Conditioner 300 ml', 'ReBorn Blonde Highlight Conditioner – pleiende balsam for blondt og bleket hår (300 ml)\r\n\r\nGi blondt, stripet og bleket hår ekstra pleie og glans med ReBorn Blonde Highlight Conditioner. Denne balsamen er utviklet for å nøytralisere uønskede varme toner, samtidig som den tilfører intens fuktighet og styrker hårfibrene. Resultatet er et jevnere, mykere og mer glansfullt hår med forlenget fargeintensitet.\r\n\r\nEgenskaper og fordeler\r\nNøytraliserer gule og oransje toner i blondt eller bleket hår\r\n\r\nTilfører intensiv fuktighet og gjør håret mykere\r\n\r\nStyrker hårfibrene med keratin og hyaluronsyre\r\n\r\nBevarer glans og beskytter mot slitasje\r\n\r\nLett formel som ikke tynger håret ned\r\n\r\nVirker raskt – perfekt i en travel hårpleierutine\r\n\r\nBruksanvisning\r\nVask håret med ReBorn Blonde Highlight Shampoo\r\n\r\nKlem ut overflødig vann fra håret\r\n\r\nPåfør balsamen jevnt i lengder og tupper\r\n\r\nLa virke i 1–3 minutter\r\n\r\nSkyll godt med lunkent vann\r\n\r\nSpesifikasjoner\r\nVolum: 300 ml\r\n\r\nType: fargebevarende balsam\r\n\r\nEffekt: nøytralisering, fuktighet, glans, styrke\r\n\r\nPasser for: blondt, stripet og bleket hår\r\n\r\n', 'reborn', 'uploads/products/1763945729_rere6.webp', 0, 'active', '2025-11-21 22:52:14', '2025-11-24 00:55:29'),
(59, 'Reborn Blonde Highlight Shampoo 300 ml', 'ReBorn Blonde Highlight Shampoo – pigmentert sjampo som demper gult (300 ml)\r\n\r\nFremhev og bevar kalde toner med ReBorn Blonde Highlight Shampoo – en fiolettpigmentert, pH-balansert shampoo designet for stripet, bleket og blondt hår. Denne innovative formelen kombinerer hyaluronsyre og keratin for å nøytralisere varme nyanser, styrke håret og tilføre fukt.\r\n\r\nEgenskaper og fordeler\r\nNøytraliserer uønskede gule og oransje toner\r\n\r\nBalansert pH gir skånsom rens\r\n\r\nInneholder hyaluronsyre og keratin for fukt og reparasjon\r\n\r\n7-dimensjonell behandling: demper varme toner, tilfører fukt, styrker hårfibrene, gir fleksibilitet, glans, beskytter mot frie radikaler og forbedrer tekstur\r\n\r\nEtterlater håret mykt, glansfullt og mer levende\r\n\r\nIdeell for regelmessig bruk for langsiktig fargebeskyttelse\r\n\r\nBruksanvisning\r\nFukt håret godt\r\n\r\nPåfør sjampo og massér inn i hodebunn og lengder\r\n\r\nLa virke kort (1-3 minutter) før du skyller grundig\r\n\r\nGjenta kun hvis nødvendig\r\n\r\nFølg gjerne opp med ReBorn Blonde Highlight Conditioner eller Mask for best effekt\r\n\r\nSpesifikasjoner\r\nVolum: 300 ml\r\n\r\nType: fiolettpigmentert shampoo\r\n\r\nBruksområde: blondt, stripet eller bleket hår\r\n\r\nEffekt: fargebeskyttelse, toning, hydrering og styrke', 'reborn', 'uploads/products/1763765559_re26.webp', 0, 'active', '2025-11-21 22:52:39', '2025-11-21 22:52:39'),
(60, 'Reborn Color Save Conditioner 500 ml', 'ReBorn Color Save Conditioner – fargebevarende og pleiende balsam (500 ml)\r\n\r\nTa vare på farget hår med ReBorn Color Save Conditioner 500 ml – en luksuriøs balsam utviklet for å forlenge fargens intensitet, gi dyptgående pleie og beskytte mot slitasje.\r\n\r\nEgenskaper og fordeler\r\nFormulert spesielt for farget og behandlet hår\r\n\r\nBidrar til fargebeskyttelse – motvirker falming og matthet\r\n\r\nTilfører intens fuktighet og mykgjøring uten å tynge\r\n\r\nForbedrer hårfibrenes elastisitet og styrke\r\n\r\nReduserer frizz og gir en jevn, glatt tekstur\r\n\r\nPasser både til daglig bruk og mer intensiv pleie\r\n\r\nBruksanvisning\r\nVask håret med en fargebesparende sjampo\r\n\r\nKlem ut overflødig vann før påføring\r\n\r\nPåfør balsamen jevnt i lengder og spisser\r\n\r\nLa virke i 2–3 minutter\r\n\r\nSkyll grundig med lunkent vann\r\n\r\nSpesifikasjoner\r\nVolum: 500 ml\r\n\r\nType: balsam / conditioner\r\n\r\nEffekt: pleie, fargebevaring, fukt, mykgjøring\r\n\r\nBruksområde: for farget, behandlet eller sensitivt hår', 'reborn', 'uploads/products/1763765583_re27.webp', 0, 'active', '2025-11-21 22:53:03', '2025-11-21 22:53:03'),
(61, 'Reborn Color Save Shampoo 500 ml', 'ReBorn Color Save Shampoo – fargebevarende reparasjon og glans (500 ml)\r\n\r\nOppretthold den levende fargen og beskytte ditt fargede hår med ReBorn Color Save Shampoo 500 ml. Dette er en avansert, pH-balansert shampoo som kombinerer reparerende teknologi og skånsom pleie for å bevare, styrke og vitalisere håret fra første vask.\r\n\r\nEgenskaper og fordeler\r\nSpesielt utviklet for farget og kjemisk behandlet hår\r\n\r\nBevarer og beskytter hårfargen, motvirker falming og matthet\r\n\r\nInneholder hyaluronsyre og keratin som gir intensiv fukt, styrke og elastisitet\r\n\r\nLukker hårfibrene og beskytter mot ytre påvirkninger\r\n\r\nSkånsom og mild formel som passer for daglig bruk\r\n\r\nTilbyr 7-i-én reparasjon: fuktighet, anti-frizz, styrke, fargebeskyttelse, fleksibilitet, jevn tekstur og glans\r\n\r\nBruksanvisning\r\nFukt håret med lunkent vann\r\n\r\nPåfør shampoo i hodebunn og lengder, massér til skum\r\n\r\nSkyll grundig\r\n\r\nGjenta ved behov\r\n\r\nFor best effekt, bruk sammen med ReBorn Color Save Conditioner / Mask\r\n\r\nSpesifikasjoner\r\nVolum: 500 ml\r\n\r\nType: fargebesparende / reparerende shampoo\r\n\r\nEffekt: fuktighet, reparasjon, fargebeskyttelse, glans\r\n\r\nAnbefalt for: farget, skadet eller behandlet hår\r\n\r\n', 'reborn', 'uploads/products/1763945846_rere8.webp', 0, 'active', '2025-11-21 22:53:29', '2025-11-24 00:57:26');
INSERT INTO `products` (`id`, `name`, `description`, `category`, `image`, `featured`, `status`, `created_at`, `updated_at`) VALUES
(62, 'Reborn Color Save Mask 250 ml', 'ReBorn Color Save Mask – profesjonell hårkur for farget hår med intensiv pleie (250 ml)\r\n\r\nGi håret en luksuriøs behandling med ReBorn Color Save Mask – en profesjonell hårkur utviklet for å bevare hårfargen, tilføre dyp fuktighet og gjenoppbygge skadet hår. Denne rike masken beskytter fargepigmentene, forhindrer falming og gjør håret silkemykt, glansfullt og fullt av liv. Perfekt for deg som vil ha langvarig fargebeskyttelse kombinert med reparasjon og næring.\r\n\r\nEgenskaper og fordeler\r\nFargebevarende hårmaske som forlenger intensiteten i hårfargen\r\n\r\nReparerende hårkur for skadet hår – styrker hårfibrene og reduserer slitasje\r\n\r\nGir intensiv fuktighet og næring takket være keratin og hyaluronsyre\r\n\r\nKontrollerer frizz og flyvehår for en jevn og glatt finish\r\n\r\nEtterlater håret mykt, smidig, glansfullt og lett å style\r\n\r\nProfesjonell hårpleie som kan brukes både hjemme og i salong\r\n\r\nBruksanvisning\r\nVask håret med en fargebevarende sjampo\r\n\r\nKlem ut overflødig vann og påfør masken i lengder og tupper\r\n\r\nLa virke i 3–5 minutter\r\n\r\nSkyll grundig ut med lunkent vann\r\n\r\nBruk 1–2 ganger i uken for best resultat\r\n\r\nSpesifikasjoner\r\nVolum: 250 ml\r\n\r\nType: fargebevarende hårkur / hårmaske\r\n\r\nEffekt: fuktighet, reparasjon, glans, fargebeskyttelse, anti-frizz\r\n\r\nAnbefales for: farget, tørt, kjemisk behandlet eller skadet hår', 'reborn', 'uploads/products/1763765636_re29.webp', 0, 'active', '2025-11-21 22:53:56', '2025-11-21 22:53:56'),
(63, 'Reborn Color Save Serum 50 ml', 'ReBorn Color Save Serum – profesjonelt serum for farget hår (50 ml)\r\n\r\nBevar hårfargen lengre og gi håret intensiv pleie med ReBorn Color Save Serum. Dette profesjonelle hårserumet er utviklet for farget, tørt og skadet hår som trenger ekstra næring, fukt og beskyttelse. Den lette leave-in formelen trekker raskt inn i hårfibrene og gir et silkemykt resultat uten å tynge.\r\n\r\nEgenskaper og fordeler\r\nFargebeskyttende serum – forlenger holdbarheten og glansen i hårfargen\r\n\r\nReparerende effekt – styrker svekket hårstruktur og gjenoppbygger skadet hår\r\n\r\nAnti-frizz og glans – reduserer krus, temmer flyvehår og tilfører speilblank glans\r\n\r\nVarmebeskyttende hårserum – beskytter mot styling med føner, rettetang og krølltang\r\n\r\nLett og silkemyk konsistens – tynger ikke ned håret og passer perfekt for daglig bruk\r\n\r\nInneholder keratin og hyaluronsyre som gir fukt, styrke og elastisitet\r\n\r\nBruksanvisning\r\nPåfør et par dråper i håndflatene etter vask\r\n\r\nFordel jevnt i lengder og tupper i fuktig hår\r\n\r\nStyle som ønsket, eller la håret lufttørke\r\n\r\nKan også brukes i tørt hår for å gi ekstra glans og kontroll\r\n\r\nSpesifikasjoner\r\nVolum: 50 ml\r\n\r\nType: leave-in hårserum\r\n\r\nEffekt: fargebeskyttelse, reparasjon, anti-frizz, varmebeskyttelse, glans\r\n\r\nHårtyper: farget hår, kjemisk behandlet hår, skadet og tørt hår', 'reborn', 'uploads/products/1763765658_re30.webp', 0, 'active', '2025-11-21 22:54:18', '2025-11-21 22:54:18'),
(64, 'Reborn Color Save Conditioner 300 ml', 'ReBorn Color Save Conditioner – fargebeskyttende og nærende balsam (300 ml)\r\n\r\nBevar intensiteten i farget hår med ReBorn Color Save Conditioner. Denne balsamen er spesielt utviklet for farget, skadet og tørt hår, med en avansert formel som gir dyp pleie uten å tynge håret.\r\n\r\nEgenskaper og fordeler\r\nSkånsom og effektiv fuktgivende balsam som hjelper med å bevare hårfargen\r\n\r\nInneholder kokosolje og sheasmør som nærer og tilfører mykhet\r\n\r\nKombinerer hyaluronsyre og keratin for å styrke hårfibrene og gjenskape vitalitet\r\n\r\nRask virketid – virker på bare tre minutter\r\n\r\nLett formulering som ikke tynger ned håret\r\n\r\nBruksanvisning\r\nVask håret med ReBorn Color Save Shampoo\r\n\r\nTrykk ut overflødig vann fra håret\r\n\r\nPåfør balsam jevnt fra midtlengder til spisser\r\n\r\nLa virke i omtrent 3 minutter\r\n\r\nSkyll grundig med lunkent vann\r\n\r\nSpesifikasjoner\r\nVolum: 300 ml\r\n\r\nType: balsam\r\n\r\nBruksområde: pleie og fargebeskyttelse for farget hår\r\n\r\n', 'reborn', 'uploads/products/1763765691_re31.webp', 0, 'active', '2025-11-21 22:54:51', '2025-11-21 22:54:51'),
(65, 'Reborn Color Save Shampoo 300 ml', 'ReBorn Color Save Shampoo – skånsom fargebevarende sjampo (300 ml)\r\n\r\nBevar og forsterk fargen i behandlet hår med ReBorn Color Save Shampoo. Denne sjampoen er utviklet for å beskytte mot fargefading samtidig som den gir fukt, mykhet og forsegler hårstrået for optimal holdbarhet.\r\n\r\nEgenskaper og fordeler\r\nSpesielt formulert for farget hår – bidrar til å bevare pigmentene\r\n\r\nKombinerer hyaluronsyre og keratin for å styrke hårfibrene og tilføre intensiv fukt\r\n\r\nLåser inn fukt og reduserer krus for jevnere hårstruktur\r\n\r\nLukker hårfibrene og beskytter mot slitasje og matthet\r\n\r\nSkånsom, pH-balansert formel som egner seg for hyppig bruk\r\n\r\nBruksanvisning\r\nFukt håret grundig med lunkent vann\r\n\r\nPåfør sjampo og massér forsiktig i hodebunn og lengder\r\n\r\nSkyll godt\r\n\r\nGjenta ved behov\r\n\r\nKombiner gjerne med ReBorn Color Save Conditioner for best effekt\r\n\r\nSpesifikasjoner\r\nVolum: 300 ml\r\n\r\nType: fargebevarende sjampo\r\n\r\nHovedvirkning: fargebeskyttelse, fukt, styrke\r\n\r\nBruksområde: hårpleie for farget og behandlet hår', 'reborn', 'uploads/products/1763945800_rere7.webp', 0, 'active', '2025-11-21 22:55:20', '2025-11-24 00:56:40'),
(66, 'Reborn Repair Conditioner 500 ml', 'ReBorn Repair Conditioner – intensiv gjenoppbyggende balsam (500 ml)\r\n\r\nReBorn Repair Conditioner 500 ml er spesielt utviklet for kjemisk behandlet, skadet og tørt hår. Denne balsamen kombinerer virkningsfulle ingredienser som hyaluronsyre, keratin og arganolje for å gi dyp pleie uten å tynge ned.\r\n\r\nEgenskaper og fordeler\r\nReparerer og gjenoppbygger hårfibrene\r\n\r\nTilfører intensiv fukt og mykgjør\r\n\r\nReduserer frizz og gir glattere overflate\r\n\r\nØker elastisitet og styrke i håret\r\n\r\nBeskytter mot skader og bevarer hårets struktur\r\n\r\nLett konsistens som ikke etterlater hår tungt\r\n\r\nBruksanvisning\r\nVask håret med ReBorn Repair Shampoo\r\n\r\nPress ut overflødig vann i håret\r\n\r\nPåfør balsamen fra ca. 1 cm over hodebunnen til tuppene\r\n\r\nLa virke i 2–3 minutter\r\n\r\nSkyll grundig med lunkent vann\r\n\r\nSpesifikasjoner\r\nVolum: 500 ml\r\n\r\nType: balsam / conditioner\r\n\r\nEffekt: reparasjon, fukt, antikruss\r\n\r\nBruksområde: hårpleie for skadet og behandlet hår', 'reborn', 'uploads/products/1763765749_re33.webp', 0, 'active', '2025-11-21 22:55:49', '2025-11-21 22:55:49'),
(67, 'Reborn Repair Shampoo 500 ml', 'ReBorn Repair Shampoo – intensiv reparasjon og gjenoppbygging (500 ml)\r\n\r\nReBorn Repair Shampoo 500 ml er spesielt formulert for kjemisk skadet, tørt eller svakt hår. Med en innovativ kombinasjon av hyaluronsyre og keratin leverer denne shampoen en syv-dimensjonal behandling som styrker, fukter, beskytter og gjenoppretter hårets struktur.\r\n\r\nEgenskaper og fordeler\r\nReparerer skadet hår og styrker hårfibrene\r\n\r\nGir intensiv fukt og mykgjøring\r\n\r\nMotvirker frizz og gir en jevn og myk tekstur\r\n\r\nØker fleksibiliteten i håret\r\n\r\nBeskytter farge og gir økt glans\r\n\r\nFri for natriumklorid (salt) og skadelige sulfater som SLS/SLES\r\n\r\nBruksanvisning\r\nFukt håret grundig\r\n\r\nPåfør shampoo og massér forsiktig i hodebunn og lengder\r\n\r\nSkyll grundig med lunkent vann\r\n\r\nGjenta vask ved behov\r\n\r\nFølg opp med ReBorn Repair Conditioner eller Repair Mask for best resultat\r\n\r\nSpesifikasjoner\r\nVolum: 500 ml\r\n\r\nBruksområde: hårpleie for skadet, kjemisk prosessert eller tørt hår\r\n\r\nHovedingredienser: hyaluronsyre og keratin\r\n\r\nEffekt: reparasjon, fukt, antikruss, styrke', 'reborn', 'uploads/products/1763765775_re34.webp', 0, 'active', '2025-11-21 22:56:15', '2025-11-21 22:56:15'),
(68, 'Reborn Repair Serum 50 ml', 'ReBorn Repair Serum – intensiv reparerende behandling (50 ml)\r\n\r\nReBorn Repair Serum er en avansert leave-in behandling utviklet for å redde skadet, frizzy eller uttørket hår. Formulert med to potente polymerer – hyaluronsyre og keratin – for å levere dyptgående fuktighet, styrke og glans uten å tynge håret.\r\n\r\nEgenskaper og fordeler\r\nGjenoppbygger hårfiber fra skjellaget til tuppene\r\n\r\nLåser inn fuktighet og reduserer krus\r\n\r\nBeskytter hårstrået under tørkeprosessen\r\n\r\nEtterlater hår mykt, smidig og med strålende glans – uten fett følelse\r\n\r\nKan brukes både i fuktig og tørt hår for ekstra pleie og kontroll\r\n\r\nBruksanvisning\r\nPå vått hår: Etter sjampo og håndkletørking, bruk en liten mengde serum i håndflatene og fordel i lengder og tuppene. Kjem gjennom for jevn fordeling før styling.\r\n\r\nPå tørt hår: Bruk en liten mengde i håndflatene, og arbeid forsiktig inn i lengder og tupper for å temme frizz og tilføre glans.\r\n\r\nSpesifikasjoner\r\nVolum: 50 ml\r\n\r\nForm: lett serum\r\n\r\nEffekt: reparasjon, fukt, frizzkontroll, glans\r\n\r\nAnbefales for: skadet, utsatt og uregjerlig hår', 'reborn', 'uploads/products/1763765813_re35.webp', 0, 'active', '2025-11-21 22:56:53', '2025-11-21 22:56:53'),
(69, 'Reborn Repair Mask 250 ml', 'ReBorn Repair Mask – intensiv reparerende hårmaske (250 ml)\r\n\r\nReBorn Repair Mask er en terapeutisk hårkur spesielt utviklet for hår som har vært utsatt for kjemiske behandlinger, varmeverktøy eller generell slitasje. Den kombinerer kraftige ingredienser for å styrke, pleie og gjenoppbygge hårfibrene.\r\n\r\nEgenskaper og fordeler\r\nFormulert med keratin, aminosyrer, kalsium og magnesium for å styrke og reparere skadet hår\r\n\r\nFuktgivende og gjenoppbyggende effekt som reduserer frizz, øker elastisitet og gir glans\r\n\r\nBalanserer pH og hjelper til med å låse pleiende ingredienser i hårstråene\r\n\r\nFri for natriumklorid (salt) — trygg for bruk etter behandlinger som keratinbehandling\r\n\r\nIdeell å bruke 1–2 ganger i uken for vedlikeholdspleie\r\n\r\nBruksanvisning\r\nVask håret grundig og klem ut overflødig vann\r\n\r\nPåfør masken jevnt i lengder og spisser, unngå direkte kontakt med hodebunnen\r\n\r\nLa virke i 5–10 minutter\r\n\r\nSkyll grundig med lunkent vann\r\n\r\nSpesifikasjoner\r\nVolum: 250 ml\r\n\r\nType: gjenoppbyggende hårmaske\r\n\r\nEffekt: reparasjon, fukt, styrke, glans\r\n\r\nPasser for: kjemisk behandlet hår, varmeeksponert hår, skrøpelig eller slitt hår', 'reborn', 'uploads/products/1763765846_re36.webp', 0, 'active', '2025-11-21 22:57:26', '2025-11-21 22:57:26'),
(70, 'Reborn Repair Conditioner 300 ml', 'ReBorn Repair Conditioner – gjenoppbyggende balsam for skadet hår (300 ml)\r\n\r\nReBorn Repair Conditioner tilbyr en luksuriøs, målrettet pleie for skadet, kjemisk behandlet eller tørt hår. Den unike formelen kombinerer hyaluronsyre og keratin med nærende oljer som arganolje for å levere dyptvirkende fukt, reparasjon og myk finish uten å tynge håret.\r\n\r\nEgenskaper og fordeler\r\nGjenoppbyggende effekt: hjelper med å reparere skadede hårfibre og styrke hårets struktur\r\n\r\nIntens fuktighet: infilitrerer hårstrået for å gi langvarig hydrering\r\n\r\nAnti-frizz og glatthet: bidrar til å dempe krus og gi en mykere overflate\r\n\r\nLett konsistens: absorberes raskt uten å etterlate restprodukter\r\n\r\nBalansert pleie: egnet for daglig bruk også på farget eller kjemisk behandlet hår\r\n\r\nBruksanvisning\r\nEtter sjamponering, klem ut overflødig vann fra håret\r\n\r\nPåfør balsamen jevnt over lengder og spisser, unngå direkte kontakt med hodebunnen\r\n\r\nLa virke i 2–3 minutter for maksimal effekt\r\n\r\nSkyll grundig med lunkent vann\r\n\r\nSpesifikasjoner\r\nVolum: 300 ml\r\n\r\nType: balsam / conditioner\r\n\r\nEffekt: reparasjon, fuktighet, styrke, antikruss\r\n\r\nPasser for: skadet, tørt, kjemisk behandlet hår\r\n\r\nHar du spørsmål?\r\n', 'reborn', 'uploads/products/1763765872_re37.webp', 0, 'active', '2025-11-21 22:57:52', '2025-11-21 22:57:52'),
(71, 'Reborn Repair Shampoo 300 ml', 'ReBorn Repair Shampoo – dyptgjenoppbyggende shampoo for skadet hår (300 ml)\r\n\r\nGi håret nytt liv med ReBorn Repair Shampoo 300 ml – en avansert, reparerende formel utviklet for kjemisk skadet, tørt eller svakt hår. Denne unike shampooen kombinerer kraftige polymerer som hyaluronsyre og keratin i én sammensetning for å reparere, styrke og forbedre hårets struktur.\r\n\r\nNøkkelfordeler og egenskaper\r\nSpesielt utviklet for skadet, behandlet og tørt hår\r\n\r\nKombinerer hyaluronsyre og keratin for å mykgjøre, styrke og gjenopprette hårets integritet\r\n\r\nTilbyr syv-dimensjonal behandling, inkludert:\r\n• Anti-frizz-effekt\r\n• Intens fukt og dyphydrering\r\n• Styrking av hårfiber\r\n• Økt fleksibilitet og elastisitet\r\n• Fargebeskyttelse\r\n• Forebygging av matthet\r\n• Nøytralisering av frie radikaler\r\n\r\nEtterlater håret mykt, glansfullt og mer håndterbart\r\n\r\nBruksanvisning\r\nFukt håret grundig med lunkent vann\r\n\r\nPåfør shampoo i hodebunn og arbeid den ut mot lengdene\r\n\r\nMassér forsiktig med fingertuppene for å skape skum\r\n\r\nSkyll grundig med vann\r\n\r\nHvis nødvendig, gjenta gjerne prosessen\r\n\r\nFor best resultat, følg opp med ReBorn Repair Conditioner eller ReBorn Repair Masque\r\n\r\nSpesifikasjoner\r\nVolum: 300 ml\r\n\r\nType: gjenoppbyggende shampoo\r\n\r\nFormulering: inneholder hyaluronsyre + keratin\r\n\r\nEffekt: reparasjon, fukt, styrke, anti-frizz og beskyttelse\r\n\r\nBruksområde: hårpleie, spesielt egnet for kjemisk eller mekanisk skadet hår\r\n\r\nSEO-nøkkelord\r\nNår du markedsfører produktet, bruk nøkkelord som ReBorn Repair Shampoo 300 ml, reparerende shampoo, shampoo for skadet hår, hyaluronsyre shampoo, keratin shampoo, anti-frizz reparasjonshårpleie i produkttittel, metabeskrivelse, kategori og tagger for optimal synlighet.', 'reborn', 'uploads/products/1763765902_re38.webp', 0, 'active', '2025-11-21 22:58:22', '2025-11-21 22:58:22');

