INSERT INTO `products_backup` (`id`, `name`, `description`, `category`, `image`, `featured`, `status`, `created_at`, `updated_at`) VALUES
(53, 'Work Out Mask', 'STĀS Work Out Mask er en effektiv og tidsbesparende hårkur utviklet for deg med en aktiv livsstil. Denne dype pleiebehandlingen styrker håret, tilfører intens fuktighet og reduserer hårbrudd – perfekt å bruke før trening, i en travel hverdag eller som nattmaske. Håret blir sunnere, sterkere og mer motstandsdyktig over tid.\r\n\r\nFordeler og egenskaper\r\nDyp fukt og intensiv næring til tørt og slitt hår\r\nReduserer hårbrudd og styrker hårstråene fra rot til spiss\r\nIdeell å bruke før trening eller som behandling over natten\r\nGjør håret mer motstandsdyktig mot ytre påkjenninger\r\nPasser for alle hårtyper – spesielt skadet, tørt eller svekket hår\r\nBruksanbefaling\r\nPåfør i tørt hår, jevnt fordelt fra midtlengde til spisser\r\nLa virke i minst 30 minutter, gjerne over natten\r\nSkyll ut med sjampo, og avslutt med balsam for best resultat\r\nAktive ingredienser\r\nVitis Vinifera (druekjerneolje): Rik på antioksidanter som styrker og beskytter\r\nCocos Nucifera (kokosolje): Gir dyp fuktighet og naturlig glans\r\nCrambe Abyssinica Seed Oil: Mykgjør og gir glans uten å tynge\r\nPhytosteroler og planteekstrakter: Bidrar til reparasjon og oppbygging av håret\r\nHva gjør STĀS Work Out Mask unik?\r\nUtviklet for en aktiv hverdag – fungerer mens du trener, jobber hjemme eller sover\r\nKombinerer styrkende og fuktighetsgivende ingredienser i én behandling\r\nReduserer brudd og tørrhet uten å tynge håret\r\nGir salongresultat hjemme, uten komplisert påføring eller ventetid\r\nHvem passer den for?\r\nDeg med tørt, slitt eller kjemisk behandlet hår\r\nDeg som vil gi håret en intensiv boost mellom frisørbesøk\r\nDeg som ønsker en enkel og effektiv hårkur som passer en hektisk hverdag\r\nEgnet for både kvinner og menn med behov for styrke og pleie\r\nVekt: 150ml', 'stas', 'uploads/products/1762167624_stas1.webp', 0, 'active', '2025-11-03 11:00:24', '2025-11-03 11:00:24'),
(54, 'Stas Hairspray', 'STĀS Hairspray er en lett og effektiv hårspray som gir et naturlig hold uten å tynge håret. Den passer perfekt til alle hårtyper og gir en fin glans samtidig som den holder frisyren på plass hele dagen.\r\n\r\nFordeler og egenskaper\r\nLett hold: Gir et naturlig og fleksibelt hold uten å gjøre håret stivt.\r\nNaturlig glans: Etterlater håret med en fin og naturlig glans.\r\nAllsidig bruk: Passer til alle hårtyper og ulike frisyrestiler.\r\nEnkel påføring: Sprayes jevnt over håret for ønsket effekt.\r\nBruksanbefaling\r\nFor et naturlig hold: Hold sprayflasken like langt fra hodet som flasken er lang.\r\nFor en mer definert frisyre: Spray nærmere håret.\r\nFor en wet-look-effekt: Bruk mer produkt og spray nærmere håret.\r\nIngredienser\r\nPolyvinylpyrrolidone (PVP): Et polymer som gir håret hold og struktur.\r\nPolydimethylsiloxane: En silikonforbindelse som gir håret glans og mykhet.\r\nAlkohol: Hjelper til med å fordampe produktet raskt og gir en lett følelse.\r\nVann: Grunnlaget for produktet som løser opp de aktive ingrediensene.\r\nHva gjør STĀS Hairspray unik?\r\nSkånsom formel: Utviklet for å være mild mot håret og hodebunnen.\r\nAllsidig: Passer for både daglig bruk og spesielle anledninger.\r\nProfesjonell kvalitet: Brukt av frisører og hårstylister for å oppnå ønsket frisyre.\r\nMålgruppe\r\nAlle hårtyper: Fra fint til tykt hår, og alt imellom.\r\nDaglig bruk: Perfekt for å holde frisyren på plass hele dagen.\r\nSpesielle anledninger: Ideell for fest eller andre spesielle hendelser.', 'stas', 'uploads/products/1762168610_stas2.webp', 0, 'active', '2025-11-03 11:16:50', '2025-11-03 11:16:50'),
(55, 'Stas BRUSH MEDIUM', 'Oppdag den perfekte balansen mellom kontroll og komfort med STAS Products Hairbrush Medium – en allsidig hårbørste som glir lett gjennom håret og gir et glatt, glansfullt resultat. Den mellomstore størrelsen gjør børsten ideell til både styling og daglig bruk – uansett hårtype.\r\n\r\nUtstyrt med fleksible børstepigger og ergonomisk design, reduserer børsten risikoen for brekkasje og gir en behagelig børsteopplevelse både i vått og tørt hår. Passer utmerket til føning, detangling og jevn fordeling av produkter i håret.\r\n\r\nEgenskaper:\r\nMedium størrelse – perfekt til både hjemmebruk og reise\r\n\r\nSkånsom mot hår og hodebunn\r\n\r\nLøsner floker uten å trekke eller skade\r\n\r\nEgnet for alle hårtyper – fra fint til tykt hår\r\n\r\nKan brukes i både vått og tørt hår\r\n\r\nKomfortabelt og lett håndtak for enkel bruk\r\n\r\nBruk:\r\nBruk på tørt eller håndkletørt hår for å løse opp floker og fordele naturlige oljer jevnt i håret. Ideell som en allround børste for daglig pleie og styling.', 'stas', 'uploads/products/1762168662_stas3.webp', 0, 'active', '2025-11-03 11:17:42', '2025-11-03 11:17:42'),
(56, 'Stas Hair oil', 'Gi håret ditt et luksuriøst løft med STAS Products Hair Oil – en eksklusiv hårolje som kombinerer næring, glans og pleie i én og samme flaske. Denne lette, men svært effektive oljen er utviklet for å styrke håret fra rot til spiss, redusere frizz og etterlate det silkemykt uten å tynge.\r\n\r\nBeriket med nøye utvalgte naturlige oljer som trenger dypt inn i hårstråene, gir denne håroljen intens fuktighet, gjenoppretter hårets elastisitet og forbedrer både glans og tekstur. Perfekt både som daglig pleie og som en kur for tørt og livløst hår.\r\n\r\nPasser for alle hårtyper – også fargebehandlet hår.\r\n\r\nEgenskaper:\r\nTilfører glans og mykhet uten å tynge håret\r\n\r\nReduserer frizz og beskytter mot ytre påvirkninger\r\n\r\nFuktighetsgivende og reparerende egenskaper\r\n\r\nEgnet for alle hårtyper, inkludert tørt og skadet hår\r\n\r\nKan brukes både i tørt og fuktig hår\r\n\r\nElegant og delikat duft\r\n\r\nBruk:\r\nPåfør et par dråper i håndflatene og fordel jevnt i lengder og spisser. Kan brukes i både vått og tørt hår – etter behov.', 'stas', 'uploads/products/1762168714_stas4.webp', 0, 'active', '2025-11-03 11:18:34', '2025-11-03 11:18:34'),
(57, 'Stas DRY TEXTURIZING', 'Få salongfølelsen hjemme med STAS Products Texturizing Big Volume – en allsidig teksturspray som gir umiddelbart løft, luftig volum og en rå tekstur med naturlig bevegelse. Perfekt for deg som ønsker et fyldigere og mer definert hår uten stivhet eller tyngde.\r\n\r\nSprayen er ideell både i røttene for løft, og i lengdene for å fremheve bevegelse og form. Den etterlater håret friskt, fleksibelt og med et naturlig matt finish. Bruk den alene for en avslappet, undone look, eller som stylingbase før oppsett og føning for ekstra hold og tekstur.\r\n\r\nEgenskaper:\r\nGir umiddelbart volum og fylde\r\n\r\nFremhever tekstur og bevegelse\r\n\r\nLett formel med fleksibelt hold\r\n\r\nPerfekt til både løst hår og oppsetninger\r\n\r\nEtterlater ikke produktrester eller klissete følelse\r\n\r\nPasser alle hårtyper – spesielt fint eller flatt hår\r\n\r\nBruk:\r\nRist godt og spray i tørt hår ved røttene for volum, eller i lengdene for tekstur og hold. Style som ønsket.', 'stas', 'uploads/products/1762168879_stas5.webp', 0, 'active', '2025-11-03 11:21:19', '2025-11-03 11:21:19'),
(58, 'Stas Hair Filler', 'Opplev synlig fyldigere og sunnere hår med STAS Products Hairfiller – en avansert leave-in behandling utviklet for å styrke, beskytte og gi volum helt fra røttene. Denne lette, men kraftfulle formelen gir en umiddelbar følelse av tykkere hår samtidig som den jobber langsiktig med å forbedre hårkvaliteten.\r\n\r\nMed et konsentrert kompleks av aktive ingredienser stimulerer Hairfiller hodebunnen, støtter hårvekst og gir styrke til svakt eller skadet hår. Perfekt for deg som ønsker mer volum, bedre tekstur og en sunnere hårfølelse – uten å bruke tunge stylingprodukter.\r\n\r\nEgenskaper:\r\nGir umiddelbart synlig volum og fylde\r\n\r\nStyrker håret fra rot til spiss\r\n\r\nStimulerer og pleier hodebunnen\r\n\r\nLett og ikke-klissete leave-in behandling\r\n\r\nMotvirker hårtap og forbedrer hårstrukturen over tid\r\n\r\nPasser alle hårtyper, også fint eller skadet hår\r\n\r\nBruk:\r\nFordel produktet jevnt i hodebunnen og hårrøttene etter vask. Masser inn og style som vanlig – skal ikke skylles ut.', 'stas', 'uploads/products/1762168911_stas6.webp', 0, 'active', '2025-11-03 11:21:51', '2025-11-03 11:21:51'),
(59, 'Stas Dry Shampoo', 'STĀS Dry Shampoo er en effektiv tørrsjampo som gir håret en nyvasket følelse uten behov for vann. Den absorberer overflødig olje og urenheter, og etterlater håret friskt, lett og voluminøst – perfekt for hektiske dager, mellom hårvask eller etter trening.\r\n\r\nFordeler og egenskaper\r\nRask oppfriskning: Fjerner fett og urenheter, og gir håret en ren følelse på sekunder.\r\nVolumgivende: Tilfører naturlig volum og tekstur til håret.\r\nMild mot hodebunnen: Skånsom formel som passer for sensitiv hodebunn.\r\nPraktisk bruk: Enkel å bruke når du er på farten eller har begrenset tid.\r\nBruksanbefaling\r\nRist flasken godt før bruk.\r\nSpray jevnt på tørt hår, spesielt ved røttene, fra ca. 20 cm avstand.\r\nLa virke i noen sekunder, og masser lett inn i hodebunnen.\r\nBørst gjennom håret for å fordele produktet jevnt.\r\nIngredienser\r\nTapioca Starch: Naturlig stivelse som absorberer overflødig olje og gir volum.\r\nMagnesium Stearate: Bidrar til en jevn fordeling og forbedrer teksturen.\r\nPEG-12 Dimethicone: Gir en myk og silkeaktig følelse uten å tynge håret.\r\nParfum: Etterlater en frisk duft.\r\nHva gjør STĀS Dry Shampoo unik?\r\nSkånsom formel: Utviklet for å være mild mot hodebunnen, ideell for daglig bruk.\r\nVolumboost: Gir håret et løft og en fyldigere følelse uten å tynge.\r\nAllsidig: Passer for alle hårtyper og kan brukes når som helst på dagen.\r\nMålgruppe\r\nTravle personer: Perfekt for de som har en hektisk hverdag og trenger en rask håroppfriskning.\r\nTreningsentusiaster: Ideell etter trening for å fjerne svette og gi håret en frisk følelse.\r\nAlle hårtyper: Passer for både tynt og tykt hår, og kan brukes daglig.', 'stas', 'uploads/products/1762168939_stas7.webp', 0, 'active', '2025-11-03 11:22:19', '2025-11-03 11:22:19'),
(62, 'fvxdfv', '\"dpsgka\\repar[ofk', 'reborn', 'uploads/products/1762248724_aesthetic-pingu-meme-desktop-wallpaper.jpg', 0, 'active', '2025-11-04 09:32:04', '2025-11-04 09:32:04');

